package com.onurkat.reclazz.transform;
import java.io.*;import java.util.*;import org.junit.jupiter.api.Test;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
import static org.junit.jupiter.api.Assertions.*;
class RecordCohortCandidatesTest {
 static ClassNode node(String name,boolean record,String... fields){var n=new ClassNode();n.visit(Opcodes.V17,Opcodes.ACC_PUBLIC|Opcodes.ACC_FINAL|(record?Opcodes.ACC_RECORD:0),name,null,record?"java/lang/Record":"java/lang/Object",null);for(int i=0;i<fields.length;i++)n.visitField(Opcodes.ACC_PUBLIC,"f"+i,"L"+fields[i]+";",null,null).visitEnd();return n;}
 static byte[] bytes(ClassNode n){var w=new ClassWriter(0);n.accept(w);return w.toByteArray();}
 static class Loader extends ClassLoader{int reads;final Map<String,byte[]> resources;Loader(Map<String,byte[]>r){super(null);resources=r;}@Override public InputStream getResourceAsStream(String name){reads++;byte[] b=resources.get(name);return b==null?null:new ByteArrayInputStream(b);}@Override protected Class<?> loadClass(String n,boolean r){throw new AssertionError("candidate scan must not define/load "+n);}}
 static boolean watched(String n){return n.startsWith("com/example/");}
 @Test void plainClassDoesNotAcquireRecordCost(){var l=new Loader(Map.of());RecordCohortCandidates.observe(l,node("com/example/Plain",false),RecordCohortCandidatesTest::watched);assertFalse(RecordCohortCandidates.retain(l,"com/example/Plain"));assertFalse(RecordCohortCandidates.candidate(l,"com/example/Plain",RecordCohortCandidatesTest::watched));}
 @Test void directRecordLinkageIsPrepared(){var r=node("com/example/R",true);var l=new Loader(Map.of("com/example/R.class",bytes(r)));RecordCohortCandidates.observe(l,node("com/example/C",false,"com/example/R"),RecordCohortCandidatesTest::watched);assertTrue(RecordCohortCandidates.retain(l,"com/example/C"));}
 @Test void recordReachingCycleNeverCachesOneMemberAsUnrelated(){var a=node("com/example/A",false,"com/example/B","com/example/R");var b=node("com/example/B",false,"com/example/A");var r=node("com/example/R",true);var l=new Loader(Map.of("com/example/A.class",bytes(a),"com/example/B.class",bytes(b),"com/example/R.class",bytes(r)));RecordCohortCandidates.observe(l,a,RecordCohortCandidatesTest::watched);assertTrue(RecordCohortCandidates.retain(l,a.name));assertTrue(RecordCohortCandidates.candidate(l,b.name,RecordCohortCandidatesTest::watched));}
 @Test void recordFreeCycleStaysOrdinary(){var a=node("com/example/A",false,"com/example/B");var b=node("com/example/B",false,"com/example/A");var l=new Loader(Map.of("com/example/A.class",bytes(a),"com/example/B.class",bytes(b)));RecordCohortCandidates.observe(l,a,RecordCohortCandidatesTest::watched);assertFalse(RecordCohortCandidates.retain(l,a.name));assertFalse(RecordCohortCandidates.candidate(l,b.name,RecordCohortCandidatesTest::watched));}
 @Test void lexicalNestOwnershipIsNotAnExecutableRecordDependency(){var n=node("com/example/Plain",false);n.nestHostClass="com/example/R";n.nestMembers=List.of("com/example/R");var l=new Loader(Map.of("com/example/R.class",bytes(node("com/example/R",true))));RecordCohortCandidates.observe(l,n,RecordCohortCandidatesTest::watched);assertFalse(RecordCohortCandidates.retain(l,n.name));}
 @Test void unavailableWatchedTypeIsConservativeWithoutLoadingIt(){var l=new Loader(Map.of());RecordCohortCandidates.observe(l,node("com/example/C",false,"com/example/Unavailable"),RecordCohortCandidatesTest::watched);assertTrue(RecordCohortCandidates.retain(l,"com/example/C"));}
 @Test void arbitraryStringTextDoesNotCreateRecordLinkage(){var n=node("com/example/Plain",false);var m=new MethodNode(Opcodes.ACC_PUBLIC|Opcodes.ACC_STATIC,"text","()Ljava/lang/String;",null,null);m.instructions.add(new LdcInsnNode("com.example.R"));m.instructions.add(new InsnNode(Opcodes.ARETURN));m.maxStack=1;n.methods.add(m);var l=new Loader(Map.of("com/example/R.class",bytes(node("com/example/R",true))));RecordCohortCandidates.observe(l,n,RecordCohortCandidatesTest::watched);assertFalse(RecordCohortCandidates.retain(l,n.name));}
 @Test void equalLoaderObjectsStillHaveIndependentInitialDecisions(){class Equal extends Loader{Equal(){super(Map.of());}@Override public boolean equals(Object o){return true;}@Override public int hashCode(){return 0;}}var first=new Equal();var second=new Equal();RecordCohortCandidates.observe(first,node("com/example/Same",true),RecordCohortCandidatesTest::watched);RecordCohortCandidates.observe(second,node("com/example/Same",false),RecordCohortCandidatesTest::watched);assertTrue(RecordCohortCandidates.retain(first,"com/example/Same"));assertFalse(RecordCohortCandidates.retain(second,"com/example/Same"));}

 @Test void positivePathsAreReusedBeforeDependenciesAreDefined(){var r=node("com/example/R",true);var hub=node("com/example/Hub",false,r.name);var l=new Loader(Map.of(r.name+".class",bytes(r),hub.name+".class",bytes(hub)));RecordCohortCandidates.observe(l,node("com/example/First",false,hub.name),RecordCohortCandidatesTest::watched);int reads=l.reads;assertEquals(2,reads);RecordCohortCandidates.observe(l,node("com/example/Second",false,hub.name),RecordCohortCandidatesTest::watched);assertEquals(reads,l.reads,"positive parent path must avoid resource re-read");assertTrue(RecordCohortCandidates.retain(l,"com/example/Second"));}
 @Test void aThirdLinkIsNotPreparedButTwoLinksAre(){var r=node("com/example/R",true);var a=node("com/example/A",false,r.name);var b=node("com/example/B",false,a.name);var l=new Loader(Map.of(r.name+".class",bytes(r),a.name+".class",bytes(a),b.name+".class",bytes(b)));RecordCohortCandidates.observe(l,node("com/example/Third",false,b.name),RecordCohortCandidatesTest::watched);assertFalse(RecordCohortCandidates.retain(l,"com/example/Third"));assertEquals(2,l.reads);RecordCohortCandidates.observe(l,b,RecordCohortCandidatesTest::watched);assertTrue(RecordCohortCandidates.retain(l,b.name));}
 @Test void fanoutResourceWorkIsBounded(){var map=new HashMap<String,byte[]>();String[] refs=new String[600];for(int n=0;n<refs.length;n++){refs[n]="com/example/Leaf"+n;map.put(refs[n]+".class",bytes(node(refs[n],false)));}var l=new Loader(map);RecordCohortCandidates.observe(l,node("com/example/Wide",false,refs),RecordCohortCandidatesTest::watched);assertFalse(RecordCohortCandidates.retain(l,"com/example/Wide"));assertEquals(256,l.reads);}
 @Test void aResourceDecisionNeverUpgradesAnAlreadyDefinedUnpreparedClass(){var r=node("com/example/R",true);var changed=node("com/example/Old",false,r.name);var l=new Loader(Map.of(r.name+".class",bytes(r),changed.name+".class",bytes(changed)));RecordCohortCandidates.observe(l,node(changed.name,false),RecordCohortCandidatesTest::watched);RecordCohortCandidates.observe(l,node("com/example/New",false,changed.name),RecordCohortCandidatesTest::watched);assertFalse(RecordCohortCandidates.retain(l,changed.name));assertTrue(RecordCohortCandidates.retain(l,"com/example/New"));}
}
